// The long tail of the kotlin.collections functions of Array<T>.
import kotlin.random.Random

fun main() {
    val a = arrayOf(5, 3, 8, 1)
    println(a.sum())
    println(a.average())
    println(arrayOf(1.5, 2.5).sum())
    println(arrayOf(1L, 2L).sum())
    println(arrayOf<Byte>(1, 2).sum())
    println(arrayOf(2, 4).toIntArray().contentToString())
    println(a.asSequence().filter { it > 2 }.toList())
    println(a.runningFold("") { acc, x -> acc + x })
    println(a.scan(0) { acc, x -> acc + x })
    println(a.runningReduce { x, y -> x + y })
    println(a.reduceIndexed { i, x, y -> x + y * i })
    println(a.reduceOrNull { x, y -> x * y })
    println(emptyArray<Int>().reduceOrNull { x, y -> x * y })
    println(a.reduceRight { x, acc -> acc - x })
    println(a.foldRight("") { x, acc -> acc + x })
    println(a.takeWhile { it > 2 })
    println(a.dropWhile { it > 2 })
    println(a.takeLastWhile { it < 8 })
    println(a.dropLastWhile { it < 8 })
    println(a.elementAt(1))
    println(a.elementAtOrNull(10))
    println(a.last { it > 3 })
    println(a.single { it == 8 })
    println(a.singleOrNull { it > 1 })
    println(a.maxBy { -it })
    println(a.minBy { -it })
    println(a.maxOfOrNull { it * 2 })
    println(a.minWith(compareBy<Int> { -it }))
    println(a.distinctBy { it % 2 })
    println(a.mapIndexedNotNull { i, x -> if (i > 1) x else null })
    println(a.flatMapIndexed { i, x -> listOf(i, x) })
    println(a.mapTo(ArrayList()) { it + 1 })
    println(a.filterTo(ArrayList()) { it > 3 })
    println(a.groupBy({ it % 2 }, { it * 10 }))
    println(a.groupingBy { it % 2 }.eachCount())
    println(a.associateBy({ it }, { it * it }))
    println(a.toSortedSet())
    println(a.toCollection(ArrayList()))
    val (p, q) = a
    println("$p $q ${a.component3()}")
    println(a.slice(1..2))
    println(a.sliceArray(1..2).contentToString())
    println((a + arrayOf(9, 9)).contentToString())
    println((a + listOf(7)).contentToString())
    println(a.zip(listOf("a", "b")))
    println(a.zip(arrayOf(1, 1, 1, 1)) { x, y -> x + y })
    println(a.sortedArrayDescending().contentToString())
    println(a.sortedArrayWith(compareBy<Int> { it % 4 }).contentToString())
    println(arrayOf(1, 3, 5, 7).binarySearch(5))
    println(arrayOf(1, 3, 5, 7).binarySearch(4))
    println(arrayOf("a", "c").binarySearch("b", naturalOrder()))
    println(arrayOf<Any>(1, "a", 2.5).filterIsInstance<String>())
    println(arrayOf(arrayOf(1, 2), arrayOf(3)).flatten())
    println(arrayOf(1 to "a", 2 to "b").unzip())
    println(arrayOf(null, 4, 5).firstNotNullOf { it })
    println(arrayOf<String?>(null, null).firstNotNullOfOrNull { it })
    val sb = StringBuilder()
    a.joinTo(sb, ", ", "[", "]")
    println(sb)
    var t = 0
    a.onEach { t += it }
    println(t)
    println(emptyArray<Int>().ifEmpty { arrayOf(0) }.contentToString())
    val b = arrayOf(1, 2, 3, 4, 5, 6)
    b.reverse(1, 4)
    println(b.contentToString())
    b.sort(0, 3)
    println(b.contentToString())
    b.sortDescending(0, 6)
    println(b.contentToString())
    b.shuffle(Random(1))
    println(b.sorted())
    println(b.random(Random(3)) in 1..6)
    try {
        emptyArray<String>().random()
    } catch (e: NoSuchElementException) {
        println(e.message)
    }
}
